import { motion } from 'framer-motion';

export default function GradientMeshBg() {
  return (
    <div
      style={{
        width: '100%',
        height: '100%',
        minHeight: 300,
        position: 'relative',
        overflow: 'hidden',
        background: 'var(--color-bg-base)',
        borderRadius: 'var(--radius-lg)',
      }}
    >
      {/* 渐变球1 */}
      <motion.div
        animate={{
          x: [0, 100, -50, 0],
          y: [0, -80, 60, 0],
          scale: [1, 1.2, 0.9, 1],
        }}
        transition={{ duration: 8, repeat: Infinity, ease: 'easeInOut' }}
        style={{
          position: 'absolute',
          top: '10%',
          left: '20%',
          width: 300,
          height: 300,
          borderRadius: '50%',
          background: 'radial-gradient(circle, var(--color-primary) 0%, transparent 70%)',
          opacity: 0.4,
          filter: 'blur(60px)',
        }}
      />
      {/* 渐变球2 */}
      <motion.div
        animate={{
          x: [0, -80, 60, 0],
          y: [0, 60, -40, 0],
          scale: [1, 0.8, 1.3, 1],
        }}
        transition={{ duration: 10, repeat: Infinity, ease: 'easeInOut' }}
        style={{
          position: 'absolute',
          top: '40%',
          right: '15%',
          width: 250,
          height: 250,
          borderRadius: '50%',
          background: 'radial-gradient(circle, var(--color-secondary) 0%, transparent 70%)',
          opacity: 0.35,
          filter: 'blur(60px)',
        }}
      />
      {/* 渐变球3 */}
      <motion.div
        animate={{
          x: [0, 50, -30, 0],
          y: [0, -50, 80, 0],
          scale: [1, 1.1, 0.95, 1],
        }}
        transition={{ duration: 12, repeat: Infinity, ease: 'easeInOut' }}
        style={{
          position: 'absolute',
          bottom: '10%',
          left: '40%',
          width: 200,
          height: 200,
          borderRadius: '50%',
          background: 'radial-gradient(circle, var(--color-accent) 0%, transparent 70%)',
          opacity: 0.3,
          filter: 'blur(60px)',
        }}
      />
    </div>
  );
}

export const gradientMeshCode = `import { motion } from 'framer-motion';

